// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed parameter: an address for `from` (fuzzer will supply many addresses);
    // we also fuzz an uint v to keep domain wide. The key distinguishing input is an empty _tos array,
    // which the fuzzer can reproduce by passing zero for the length via constructing the calldata below.
    function testFuzz_property(address from, uint256 v) public {
        // We will call transfer with an empty address[] for _tos. The reference implementation REQUIRES non-empty and thus reverts.
        // The mutant removed that require and will return true instead. We observe this by try/catch and assert that the reference always reverts for empty _tos.

        // Construct an empty address[] in memory and call transfer.
        address[] memory tos = new address[](0);

        bool ok;
        try c.transfer(from, address(this), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For ALL inputs the reference contract should revert (ok == false) when _tos is empty.
        // The buggy mutant will return true for some inputs (ok == true) — the fuzzer will find that mutant and make this test fail.
        assertTrue(ok == false);
    }
}
